import type { PostHogConfig } from './types'

declare const __POSTHOG_API_KEY__: string
declare const __POSTHOG_HOST__: string

// Populated by esbuild during the release build
export const getPostHogConfig = (): PostHogConfig => ({
    apiKey: __POSTHOG_API_KEY__,
    host: __POSTHOG_HOST__ || 'https://sdk-a.service-now.com',
})
